interface.signature:
POST /api/v1/auth/login
Request: { email: string, password: string, rememberMe?: boolean }
Response: { data: { accessToken: string, user: UserResponse } }

interface AuditService {
  void logLoginSuccess(User user, HttpServletRequest request);
  void logLoginFailure(User user, String email, String reason, HttpServletRequest request);
  void logPasswordResetRequest(User user, HttpServletRequest request);
  void logPasswordResetCompleted(User user, HttpServletRequest request);
}

interface EmailService {
  void sendPasswordResetEmail(String toEmail, String resetToken, String resetUrl);
}

POST /api/v1/users
Request: { email: string, password: string, fullName: string, role?: string }
Response: { data: UserResponse }

PUT /api/v1/users/{id}/role
Request: { role: string }
Response: { data: UserResponse }
Authorization: ADMIN or CHIEF_ACCOUNTANT only

POST /api/v1/invitations
Request: { email: string, role?: string }
Response: { data: { invitationToken: string, expiresAt: LocalDateTime } }
Authorization: ADMIN or CHIEF_ACCOUNTANT only

GET /api/v1/invitations/{token}
Response: { data: { email: string, companyName: string, role: string, expiresAt: LocalDateTime } }
Authorization: Public

POST /api/v1/invitations/{token}/accept
Request: { password: string, confirmPassword: string, fullName: string }
Response: { data: { user: UserResponse, accessToken: string } }
Authorization: Public
